import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugin.MojoFailureException;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.stream.Stream;

/**
 * Minimal offline stand-in for maven-resources-plugin's "resources" goal:
 * recursively copies src/main/resources into the build output directory.
 */
public class ResourcesMojo extends AbstractMojo {

    private File basedir;
    private File outputDirectory;
    private String resourcesDirectory = "src/main/resources";

    public void setBasedir(File basedir) {
        this.basedir = basedir;
    }

    public void setOutputDirectory(File outputDirectory) {
        this.outputDirectory = outputDirectory;
    }

    public void setResourcesDirectory(String resourcesDirectory) {
        this.resourcesDirectory = resourcesDirectory;
    }

    @Override
    public void execute() throws MojoExecutionException, MojoFailureException {
        if (basedir == null || outputDirectory == null) {
            getLog().warn("resources goal skipped: basedir/outputDirectory not injected");
            return;
        }
        Path src = basedir.toPath().resolve(resourcesDirectory);
        if (!Files.isDirectory(src)) {
            getLog().info("no resources directory at " + src + ", nothing to copy");
            return;
        }
        try (Stream<Path> files = Files.walk(src)) {
            for (Path file : (Iterable<Path>) files::iterator) {
                if (Files.isDirectory(file)) {
                    continue;
                }
                Path target = outputDirectory.toPath().resolve(src.relativize(file).toString());
                Files.createDirectories(target.getParent());
                Files.copy(file, target, StandardCopyOption.REPLACE_EXISTING);
            }
        } catch (IOException e) {
            throw new MojoExecutionException("failed to copy resources from " + src, e);
        }
        getLog().info("copied resources from " + src + " to " + outputDirectory);
    }
}
