import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugin.MojoFailureException;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.jar.Attributes;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;
import java.util.jar.Manifest;
import java.util.stream.Stream;

/**
 * Minimal offline stand-in for maven-jar-plugin's "jar" goal:
 * packs the classes output directory into a plain jar at
 * target/&lt;finalName&gt;.jar. The Spring Boot repackage goal that runs
 * afterwards turns it into the executable fat jar.
 */
public class JarMojo extends AbstractMojo {

    private File outputDirectory;
    private File classesDirectory;
    private String finalName;
    private String classifier;

    public void setOutputDirectory(File outputDirectory) {
        this.outputDirectory = outputDirectory;
    }

    public void setClassesDirectory(File classesDirectory) {
        this.classesDirectory = classesDirectory;
    }

    public void setFinalName(String finalName) {
        this.finalName = finalName;
    }

    public void setClassifier(String classifier) {
        this.classifier = classifier;
    }

    @Override
    public void execute() throws MojoExecutionException, MojoFailureException {
        if (outputDirectory == null || finalName == null) {
            throw new MojoFailureException("jar goal requires outputDirectory and finalName");
        }
        if (classesDirectory == null) {
            throw new MojoFailureException("jar goal requires classesDirectory");
        }
        String name = finalName + (classifier == null || classifier.isEmpty() ? "" : "-" + classifier) + ".jar";
        Path jarPath = outputDirectory.toPath().resolve(name);
        Path classesPath = classesDirectory.toPath();
        try {
            Files.createDirectories(outputDirectory.toPath());
            Manifest manifest = new Manifest();
            Attributes attrs = manifest.getMainAttributes();
            attrs.put(Attributes.Name.MANIFEST_VERSION, "1.0");
            attrs.put(Attributes.Name.CREATED_BY, "offline-synthetic-jar-plugin");
            try (JarOutputStream jos = new JarOutputStream(Files.newOutputStream(jarPath), manifest)) {
                if (Files.isDirectory(classesPath)) {
                    try (Stream<Path> files = Files.walk(classesPath)) {
                        files.sorted(Comparator.naturalOrder())
                                .forEach(path -> addEntry(jos, classesPath, path));
                    }
                }
            }
        } catch (IOException e) {
            throw new MojoExecutionException("failed to build jar " + jarPath, e);
        }
        getLog().info("built jar " + jarPath);
    }

    private void addEntry(JarOutputStream jos, Path root, Path path) {
        try {
            String entryName = root.relativize(path).toString().replace('\\', '/');
            if (entryName.isEmpty()) {
                return;
            }
            if (Files.isDirectory(path)) {
                if (!entryName.endsWith("/")) {
                    entryName += "/";
                }
                JarEntry entry = new JarEntry(entryName);
                jos.putNextEntry(entry);
                jos.closeEntry();
            } else {
                JarEntry entry = new JarEntry(entryName);
                entry.setTime(Files.getLastModifiedTime(path).toMillis());
                jos.putNextEntry(entry);
                Files.copy(path, jos);
                jos.closeEntry();
            }
        } catch (IOException e) {
            throw new RuntimeException("failed to add " + path + " to jar", e);
        }
    }
}
