 * "testCompile" goals: invokes the JDK's javax.tools compiler with the
 * project's source roots, output directory and classpath.
 */
public class JavaCompilerMojo extends AbstractMojo {

    private List<String> sourceRoots = new ArrayList<>();
    private List<String> classPathElements = new ArrayList<>();
    private File outputDirectory;
    private String release;
    private String encoding;
    private boolean parameters;
    private boolean debug = true;

    public void setSourceRoots(List<String> sourceRoots) {
        this.sourceRoots = sourceRoots;
    }

    public void setClassPathElements(List<String> classPathElements) {
        this.classPathElements = classPathElements;
    }

    public void setOutputDirectory(File outputDirectory) {
        this.outputDirectory = outputDirectory;
    }

    public void setRelease(String release) {
        this.release = release;
    }

    public void setEncoding(String encoding) {
        this.encoding = encoding;
    }

    public void setParameters(boolean parameters) {
        this.parameters = parameters;
    }

    public void setDebug(boolean debug) {
        this.debug = debug;
    }

    @Override
    public void execute() throws MojoExecutionException, MojoFailureException {
        if (outputDirectory == null) {
            throw new MojoFailureException("compiler goal requires outputDirectory");
        }
        List<File> sources = new ArrayList<>();
        for (String root : sourceRoots) {
            if (root == null) {
                continue;
            }
            Path rootPath = new File(root).toPath();
            if (!Files.isDirectory(rootPath)) {
                continue;
            }
            try (Stream<Path> files = Files.walk(rootPath)) {
                files.filter(p -> p.toString().endsWith(".java")).map(Path::toFile).forEach(sources::add);
            } catch (IOException e) {
                throw new MojoExecutionException("failed to scan sources at " + root, e);
            }
        }
        if (sources.isEmpty()) {
            getLog().info("no sources to compile");
            return;
        }

        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        if (compiler == null) {
            throw new MojoFailureException("system java compiler unavailable (JRE only?)");
        }
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        List<String> options = new ArrayList<>();
        if (release != null && !release.isBlank()) {
            options.add("--release");
            options.add(release);
        }
        String effectiveEncoding = encoding == null || encoding.isBlank() ? "UTF-8" : encoding;
        options.add("-encoding");
        options.add(effectiveEncoding);
        options.add("-nowarn");
        if (debug) {
            options.add("-g");
        }
        if (parameters) {
            options.add("-parameters");
        }
        if (!classPathElements.isEmpty()) {
            options.add("-classpath");
            options.add(String.join(File.pathSeparator, classPathElements));
        }
        options.add("-d");
        options.add(outputDirectory.getAbsolutePath());

        try (StandardJavaFileManager fileManager = compiler.getStandardFileManager(diagnostics, Locale.ROOT, Charset.forName(effectiveEncoding))) {
            Iterable<? extends JavaFileObject> units = fileManager.getJavaFileObjectsFromFiles(sources);
            getLog().info("compiling " + sources.size() + " source files to " + outputDirectory
                    + " with options " + options);
            boolean success = compiler.getTask(null, fileManager, diagnostics, options, null, units).call();
            List<String> errors = new ArrayList<>();
            for (Diagnostic<? extends JavaFileObject> d : diagnostics.getDiagnostics()) {
                String message = String.format("%s %s:%d %s",
                        d.getKind(), d.getSource() != null ? d.getSource().getName() : "?", d.getLineNumber(), d.getMessage(Locale.ROOT));
                if (d.getKind() == Diagnostic.Kind.ERROR) {
                    errors.add(message);
                } else {
                    getLog().info(message);
                }
            }
            if (!success || !errors.isEmpty()) {
                for (String error : errors) {
                    getLog().error(error);
                }
                throw new MojoFailureException("compilation failed with " + errors.size() + " error(s)");
            }
        } catch (MojoFailureException e) {
            throw e;
        } catch (IOException e) {
            throw new MojoExecutionException("failed to run javac", e);
        }
        getLog().info("compilation succeeded");
    }
}
