    }

    @PostMapping
    public ApiResponse<Project> create(@RequestBody Project body, HttpServletRequest request) {
        Long userId = (Long) request.getAttribute("userId");
        Project created = projectService.create(body.getName(), body.getDescription(), userId);
        return ApiResponse.success("创建成功", created);
    }

    @PutMapping("/{id}")
    public ApiResponse<Project> update(@PathVariable("id") Long id, @RequestBody Project body) {
        Project updated = projectService.update(id, body.getName(), body.getDescription(), body.getStatus());
        if (updated == null) {
            return ApiResponse.error(404, "项目不存在");
        }
        return ApiResponse.success("更新成功", updated);
    }

    @DeleteMapping("/{id}")
    public ApiResponse<Void> delete(@PathVariable("id") Long id, HttpServletRequest request) {
        String role = (String) request.getAttribute("userRole");
        if (!"ADMIN".equals(role)) {
            return ApiResponse.error(403, "权限不足");
        }
        boolean deleted = projectService.delete(id);
        if (!deleted) {
            return ApiResponse.error(404, "项目不存在");
        }
        return ApiResponse.success("删除成功", null);
    }
}

